import mongoose, { Schema, Document } from "mongoose";

export interface IAbout extends Document {
  profileImage: string;
  name: string;
  story: string;
  resumeUrl: string;
}

const AboutSchema: Schema = new Schema(
  {
    // Stores relative/public path (e.g., /api/uploads/about/...) generated by the local server filesystem upload logic instead of S3 URLs
    profileImage: { type: String },
    name: { type: String, required: true },
    story: { type: String, required: true },
    // Stores relative/public path (e.g., /api/uploads/resume/...) generated by the local server filesystem upload logic instead of S3 URLs
    resumeUrl: { type: String },
  },
  { timestamps: true }
);

if (mongoose.models.About) {
  delete mongoose.models.About;
}

export default mongoose.model<IAbout>("About", AboutSchema);
